const KEY='sellsnap-drafts-v1';let drafts=[];try{drafts=JSON.parse(localStorage.getItem(KEY)||'[]')}catch{}let current=null;const $=q=>document.querySelector(q),persist=()=>localStorage.setItem(KEY,JSON.stringify(drafts)),esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function gather(){return{name:$('#name').value.trim(),brand:$('#brand').value.trim(),category:$('#category').value.trim(),condition:$('#condition').value,price:$('#price').value,dimensions:$('#dimensions').value.trim(),delivery:$('#delivery').value.trim(),features:$('#features').value.trim(),defects:$('#defects').value.trim(),photos:[...($('#photos').files||[])].map(f=>f.name),id:current?.id||crypto.randomUUID(),updated:new Date().toISOString()}}function listing(i){let title=[i.brand,i.name,i.category].filter(Boolean).join(' ');if(i.dimensions)title+=` · ${i.dimensions}`;const lines=[`${i.name}${i.brand?' · '+i.brand:''}`,`Condition: ${i.condition}`,i.features?`Details: ${i.features}`:'',i.defects?`Wear/defects: ${i.defects}`:'',i.dimensions?`Size: ${i.dimensions}`:'',i.delivery?`Pickup/shipping: ${i.delivery}`:'',i.price?`Asking price: $${Number(i.price).toLocaleString()}`:'Price: [enter your price]',i.photos?.length?`Photos selected: ${i.photos.join(', ')}`:'Add clear photos showing all sides and any wear.'].filter(Boolean);return{title,text:lines.join('\n')}}function show(i){current=i;const x=listing(i);$('#previewTitle').textContent=x.title;$('#previewText').textContent=x.text}$('#itemForm').onsubmit=e=>{e.preventDefault();show(gather())};$('#photos').onchange=e=>{$('#photoPreview').innerHTML=[...e.target.files].map(f=>`<figure><img src="${URL.createObjectURL(f)}" alt="Selected item photo"><figcaption>${esc(f.name)}</figcaption></figure>`).join('')};$('#saveDraft').onclick=()=>{if(!current)current=gather();const i=drafts.findIndex(d=>d.id===current.id);if(i<0)drafts.unshift(current);else drafts[i]=current;persist();$('#saveDraft').textContent='Saved ✓';setTimeout(()=>$('#saveDraft').textContent='Save draft',900)};$('#copy').onclick=async()=>{if(!current)current=gather();const x=listing(current);await navigator.clipboard?.writeText(x.title+'\n\n'+x.text);$('#copy').textContent='Copied';setTimeout(()=>$('#copy').textContent='Copy text',900)};$('#export').onclick=()=>{if(!current)current=gather();const x=listing(current),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([`${x.title}\n\n${x.text}`],{type:'text/plain'}));a.download='sellsnap-listing.txt';a.click();URL.revokeObjectURL(a.href)};function render(){ $('#drafts').innerHTML=drafts.length?drafts.map((d,i)=>{const x=listing(d);return `<article class="draft"><b>${esc(x.title)}</b><p>${esc(d.updated?.slice(0,10))} · ${esc(d.condition)}</p><button data-open="${i}">Open</button><button data-delete="${i}">Delete</button></article>`}).join(''):'No saved drafts.';document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{const d=drafts[+b.dataset.open];current=d;for(const k of ['name','brand','category','condition','price','dimensions','delivery','features','defects'])$('#'+k).value=d[k]||'';show(d);document.querySelector('[data-page="create"]').click()});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{drafts.splice(+b.dataset.delete,1);persist();render()})}document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id===b.dataset.page));render()});render();
